1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"strings"
7		"testing"
8	
9		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
10	)
11	
12	// runReplicateRaw 执行一次 replicate，断言正常完成（退出码 0、stderr 为空），
13	// 同时返回解码后的结果与原始输出文本：conflict 键“完全不出现”与“出现但为
14	// null”只能通过原始文本区分。
15	func runReplicateRaw(t *testing.T, input string) (mevwatch.ReplicateOutput, string) {
16		t.Helper()
17		var stdout, stderr bytes.Buffer
18		code := runReplicateIO(strings.NewReader(input), &stdout, &stderr)
19		if code != 0 {
20			t.Fatalf("exit code = %d, stderr=%s", code, stderr.String())
21		}
22		if stderr.Len() != 0 {
23			t.Fatalf("replication rejection is normal output, stderr must be empty, got %q", stderr.String())
24		}
25		var out mevwatch.ReplicateOutput
26		if err := json.Unmarshal(stdout.Bytes(), &out); err != nil {
27			t.Fatalf("stdout is not valid JSON: %v\n%s", err, stdout.String())
28		}
29		return out, stdout.String()
30	}
31	
32	// TestCLIConflictHintTermMismatchApplyKV 端到端锁定前置索引存在但任期不同时的
33	// 拒绝答复（开启 applyKV）：本地四条日志任期依次为 1、2、2、2，已提交到 3
