138			t.Fatalf("expected prev-log-mismatch rejection, got %+v", result)
139		}
140		if result.Conflict == nil ||
141			*result.Conflict != (mevwatch.ConflictHint{Index: 3, Term: 0}) {
142			t.Fatalf("conflict = %+v, want {index 3, term 0} (last local index plus one)",
143				result.Conflict)
144		}
145		if result.Term != 1 || result.CommittedIndex != 2 {
146			t.Fatalf("rejection must not change state, got term %d ci %d, want term 1 ci 2",
