162	// TestCLIConflictHintEmptyLogApplyKVShape 端到端锁定空日志开启 applyKV 时的拒绝
163	// 输出形状：前置索引越过末尾（空日志）建议为 index 1、term 0；应用字段仍完整
164	// 出现——已应用位置为 0、键值表为 {}、应用错误为 null，而不是整体缺省。
165	func TestCLIConflictHintEmptyLogApplyKVShape(t *testing.T) {
166		input := `{
167		  "currentTerm": 0,
168		  "committedIndex": 0,
169		  "log": [],
170		  "applyKV": true,
171		  "requests": [
172		    {"term": 1, "prevLogIndex": 3, "prevLogTerm": 2, "entries": [], "leaderCommit": 0}
173		  ]
174		}`
175		out, body := runReplicateRaw(t, input)
176		if len(out.Results) != 1 {
177			t.Fatalf("expected 1 result, got %+v", out.Results)
178		}
179		result := out.Results[0]
180		if result.Accepted || result.Reason != mevwatch.ReasonPrevLogMismatch {
181			t.Fatalf("expected prev-log-mismatch rejection, got %+v", result)
182		}
