190		}
191		if out.FinalAppliedIndex == nil || *out.FinalAppliedIndex != 0 {
192			t.Fatalf("finalAppliedIndex = %+v, want 0", out.FinalAppliedIndex)
193		}
194		if len(out.FinalKV) != 0 {
195			t.Fatalf("finalKV = %v, want empty", out.FinalKV)
196		}
197		if out.FinalApplyError != nil {
198			t.Fatalf("unexpected final apply error: %+v", out.FinalApplyError)
199		}
200		for _, fragment := range []string{
201			`"appliedIndex": 0`,
202			`"applyError": null`,
203			`"finalAppliedIndex": 0`,
204			`"finalKV": {}`,
205			`"finalApplyError": null`,
206			`"conflict"`,
