package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"

	"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
)

// replicateInput 是 replicate 子命令从标准输入读取的 JSON。
type replicateInput struct {
	CurrentTerm    int                 `json:"currentTerm"`
	CommittedIndex int                 `json:"committedIndex"`
	Log            []mevwatch.LogEntry `json:"log"`
	ApplyKV        bool                `json:"applyKV"`
	Requests       []replicateRequest  `json:"requests"`
}

// replicateRequest 是命令行输入层的复制请求。数值字段使用 nullableInt，
// 这样显式写成 null 时能与“省略”区分：省略取默认零值，null 是字段类型错误
// （解码在 UnmarshalJSON 中被整体拒绝）。
type replicateRequest struct {
	Term         nullableInt         `json:"term"`
	PrevLogIndex nullableInt         `json:"prevLogIndex"`
	PrevLogTerm  nullableInt         `json:"prevLogTerm"`
	Entries      []replicateLogEntry `json:"entries"`
	LeaderCommit nullableInt         `json:"leaderCommit"`
}

// replicateLogEntry 是命令行输入层的日志条目；index/term 的 null 与省略
// 同样必须区分（见 replicateRequest）。
type replicateLogEntry struct {
	Index   nullableInt `json:"index"`
	Term    nullableInt `json:"term"`
	Command string      `json:"command"`
}

// runReplicate 从标准输入读取一份 JSON（初始状态 + 顺序到达的复制请求），
// 把逐次接收结果与最终日志作为一份 JSON 写到标准输出。
// 初始状态非法或 JSON 无法解析时，以非零退出码和明确错误结束。
func runReplicate() int {
	return runReplicateIO(os.Stdin, os.Stdout, os.Stderr)
}

func runReplicateIO(stdin io.Reader, stdout, stderr io.Writer) int {
	data, err := io.ReadAll(stdin)
	if err != nil {
		fmt.Fprintf(stderr, "replicate: read stdin: %v\n", err)
		return 1
	}
	var input replicateInput
	dec := json.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&input); err != nil {
		fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
		return 1
	}
	initial, requests, err := input.toModel()
	if err != nil {
		// 显式 null 等字段类型错误在读取输入阶段失败：不输出任何结果，
		// 错误消息保留 replicate: 前缀并指出字段完整位置。
		fmt.Fprintf(stderr, "replicate: %v\n", err)
		return 1
	}
	output, err := mevwatch.ReplicateWithOptions(initial, requests, mevwatch.ReplicateOptions{ApplyKV: input.ApplyKV})
	if err != nil {
		fmt.Fprintf(stderr, "replicate: %v\n", err)
		return 1
	}
	encoded, err := json.MarshalIndent(output, "", "  ")
	if err != nil {
		fmt.Fprintf(stderr, "replicate: encode output JSON: %v\n", err)
		return 1
	}
	fmt.Fprintln(stdout, string(encoded))
	return 0
}

// toModel 把命令行输入层结构转成复制逻辑使用的类型，并把已识别数值字段上
// 显式写出的 null 报告为带完整位置的字段类型错误。路径约定：
//   - 初始字段直接给出 JSON 字段名（currentTerm、committedIndex）；
//   - 请求从 0 开始计数：requests[i].term 等；
//   - 日志条目从 0 开始计数：log[j].index 与 requests[i].entries[j].term。
func (in replicateInput) toModel() (mevwatch.InitialState, []mevwatch.AppendRequest, error) {
	initial := mevwatch.InitialState{
		CurrentTerm:    int(in.CurrentTerm),
		CommittedIndex: int(in.CommittedIndex),
		Log:            make([]mevwatch.LogEntry, 0, len(in.Log)),
	}
	for j, entry := range in.Log {
		model, err := entry.toModel()
		if err != nil {
			return mevwatch.InitialState{}, nil, fmt.Errorf("invalid input: log[%d].%s", j, err)
		}
		initial.Log = append(initial.Log, model)
	}
	requests := make([]mevwatch.AppendRequest, 0, len(in.Requests))
	for i, request := range in.Requests {
		model := mevwatch.AppendRequest{
			Term:         int(request.Term),
			PrevLogIndex: int(request.PrevLogIndex),
			PrevLogTerm:  int(request.PrevLogTerm),
			Entries:      make([]mevwatch.LogEntry, 0, len(request.Entries)),
			LeaderCommit: int(request.LeaderCommit),
		}
		for j, entry := range range request.Entries {
			modelEntry, err := entry.toModel()
			if err != nil {
				return mevwatch.InitialState{}, nil, fmt.Errorf("invalid input: requests[%d].entries[%d].%s", i, j, err)
			}
			model.Entries = append(model.Entries, modelEntry)
		}
		requests = append(requests, model)
	}
	return initial, requests, nil
}

