207	// pathPrefix 是该层字段的位置前缀：根对象为空串（错误形如 committedIndex），
208	// 其余以点号结尾（如 "requests[0]."、"log[2]."）。
209	func decodeNumericObject(object map[string]json.RawMessage, numericFields map[string]struct{}, pathPrefix string, assign func(canonicalKey string, value json.RawMessage) error) error {
210		for rawKey, value := range object {
211			canonical, matched := matchNumericKey(rawKey, numericFields)
212			if !matched {
213				continue
214			}
215			if isNull(value) {
216				return fmt.Errorf("invalid input: field %s%s must be a number, got null", pathPrefix, canonical)
217			}
218			if err := assign(canonical, value); err != nil {
219				// 数值字段写成字符串、布尔或对象等错误类型沿用 JSON 解码错误。
220				return fmt.Errorf("parse input JSON: %v", err)
221			}
222		}
223		return nil
224	}
225	
226	// matchNumericKey 按 encoding/json 的字段名匹配规则报告 objectKey 是否命中
227	// 某个已识别数值字段：比较按 Unicode 大小写折叠（等价于 bytes.EqualFold），
228	// 只改字母大小写的键名返回它命中的规范字段名。
229	func matchNumericKey(objectKey string, numericFields map[string]struct{}) (string, bool) {
230		for canonical := range numericFields {
231			if bytes.EqualFold([]byte(objectKey), []byte(canonical)) {
232				return canonical, true
233			}
234		}
235		return "", false
236	}
237	
238	// lookupKey 按字段匹配规则（大小写折叠）取出对象中某个已识别键的原始值。
239	func lookupKey(object map[string]json.RawMessage, key string) (json.RawMessage, bool) {
240		for objectKey, value := range object {
241			if bytes.EqualFold([]byte(objectKey), []byte(key)) {
242				return value, true
243			}
244		}
245		return nil, false
246	}
247	
248	// isNull 报告原始 JSON 值是否为显式 null（允许空白）。
249	func isNull(raw json.RawMessage) bool {
250		return bytes.Equal(bytes.TrimSpace(raw), []byte("null"))
251	}
